// The Docker image copies ONLY `api/`, so the server cannot read
// `platform/base.json` or `package.json` to learn its own version — it reads
// `api/build-manifest.json`, and `api/Dockerfile` copies that file in.
//
// The file was missing on 2026-08-15 and every image build failed with
// "COPY build-manifest.json ... not found". It is generated by scripts/build.mjs
// from the same `platform/base.json` that every browser manifest comes from,
// so there is no second place to type a version. This test fails if it drifts,
// disappears, or stops being copied.
import assert from "node:assert/strict";
import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const projectRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const read = (rel) => readFile(path.join(projectRoot, rel), "utf8");

const base = JSON.parse(await read("platform/base.json"));

let raw;
try {
  raw = await read("api/build-manifest.json");
} catch {
  assert.fail(
    "api/build-manifest.json is missing — run `npm run build`, and commit the file: " +
    "the Docker build COPYs it and fails without it",
  );
}

const manifest = JSON.parse(raw);
assert.equal(
  manifest.schema,
  "tp.build-manifest/1",
  "backend/config.py skips a manifest whose schema is not tp.build-manifest/1, " +
  "and then reports the version as \"unknown\"",
);
assert.equal(
  manifest.version,
  base.version,
  `api/build-manifest.json says ${manifest.version} but platform/base.json says ${base.version}`,
);

// The Dockerfile must still be the reason this file exists.
const dockerfile = await read("api/Dockerfile");
assert.match(
  dockerfile,
  /^COPY build-manifest\.json/m,
  "api/Dockerfile must copy build-manifest.json, or the container loses its version",
);

// And the generator must stay in the build, or the file goes stale the next
// time the version is bumped.
const build = await read("scripts/build.mjs");
assert.match(
  build,
  /api", "build-manifest\.json"/,
  "scripts/build.mjs must generate api/build-manifest.json",
);

console.log(`Build manifest test passed: api/build-manifest.json @ ${manifest.version}, copied by the Dockerfile.`);
